-- 30일치 통화 기록 (2025-01-01 ~ 2025-01-30)

-- 통화별 질문/답변 (완료된 통화에만, 간단히 2개씩)
SELECT id, 1, '오늘 밥 드셨나요?', '응, 먹었어.', started_at FROM call_log WHERE status = 'COMPLETED';
SELECT id, 2, '오늘 기분 어떠세요?', '그럭저럭 괜찮아요.', started_at FROM call_log WHERE status = 'COMPLETED';

-- 30일치 평가 지표 (완료된 통화에만, 위험도가 완만하게 오르내리는 패턴)

-- 이행기록 (아침 식사/복약, 간단히 랜덤성 있게)
SELECT id, 'MEAL', 'BREAKFAST', TRUE, (id % 5 <> 0) FROM assessment;
SELECT id, 'MEDICATION', 'BREAKFAST', TRUE, (id % 4 <> 0) FROM assessment;